import csv
from datetime import datetime

def parse_time(s):
    return datetime.strptime(s, '%Y-%m-%d %H:%M')

appointments = []
with open('appointments.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        appointments.append({
            'id': row['id'],
            'staff': row['staff'],
            'start': parse_time(row['start']),
            'end': parse_time(row['end'])
        })

conflicts = []
# group by staff
by_staff = {}
for appt in appointments:
    by_staff.setdefault(appt['staff'], []).append(appt)

for staff, appts in by_staff.items():
    n = len(appts)
    for i in range(n):
        for j in range(i+1, n):
            a = appts[i]
            b = appts[j]
            # check overlap half-open
            if a['start'] < b['end'] and b['start'] < a['end']:
                # conflict
                pair = sorted([a['id'], b['id']])
                conflicts.append(pair)

# sort each pair already sorted, now sort list of pairs
conflicts.sort(key=lambda x: (x[0], x[1]))
output = {"conflicts": conflicts}
import json
with open('conflicts.json', 'w') as f:
    json.dump(output, f, indent=2)
print(len(conflicts))

import json
import sys

def compute_attribution(data):
    credit = {}
    for conv in data:
        value = conv['value']
        tp = conv['touchpoints']
        n = len(tp)
        if n == 0:
            continue
        shares = [0.0] * n
        if n == 1:
            shares[0] = 1.0
        elif n == 2:
            shares[0] = 0.5
            shares[1] = 0.5
        else:
            # n >=3
            shares[0] = 0.4
            shares[-1] = 0.4
            remaining = 0.2
            if n > 2:
                per_middle = remaining / (n - 2)
                for i in range(1, n-1):
                    shares[i] = per_middle
        # accumulate
        for channel, share in zip(tp, shares):
            credit[channel] = credit.get(channel, 0.0) + value * share
    # round to 2 decimals
    rounded = {ch: round(amt, 2) for ch, amt in credit.items()}
    return {"credit": rounded}

if __name__ == '__main__':
    # read from stdin or file
    if len(sys.argv) > 1:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)
    else:
        data = json.load(sys.stdin)
    result = compute_attribution(data)
    print(json.dumps(result, indent=2))

