import csv
import json
from datetime import datetime

def main():
    q3_start = datetime(2026, 7, 1)
    q3_end = datetime(2026, 9, 30)
    rep_totals = {}
    with open('deals.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            close_date = datetime.strptime(row['close_date'], '%Y-%m-%d')
            if q3_start <= close_date <= q3_end and row['refunded'].lower() == 'no':
                rep = row['rep']
                amount = float(row['amount'])
                rep_totals[rep] = rep_totals.get(rep, 0.0) + amount
    payouts = {}
    total_payout = 0.0
    for rep, total in rep_totals.items():
        if total <= 0:
            continue
        if total <= 50000:
            commission = total * 0.05
        else:
            commission = 2500 + (total - 50000) * 0.08
        commission = round(commission, 2)
        payouts[rep] = commission
        total_payout += commission
    total_payout = round(total_payout, 2)
    result = {"payouts": payouts, "total_payout": total_payout}
    with open('commission.json', 'w') as out:
        json.dump(result, out, indent=2)

if __name__ == '__main__':
    main()

