import csv
import datetime
import json

# holidays
holidays = {
    datetime.date(2026, 11, 26),
    datetime.date(2026, 11, 27),
    datetime.date(2026, 12, 25),
}

def is_business_day(d):
    if d.weekday() >= 5:  # Saturday=5, Sunday=6
        return False
    if d in holidays:
        return False
    return True

def add_business_days(start_date, n):
    """Return date that is n business days after start_date."""
    current = start_date
    count = 0
    while count < n:
        current += datetime.timedelta(days=1)
        if is_business_day(current):
            count += 1
    return current

def parse_date(s):
    return datetime.datetime.strptime(s, "%Y-%m-%d").date()

def main():
    reminders = {}
    with open('invoices.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            inv_id = row['invoice_id']
            due = parse_date(row['due_date'])
            paid_str = row['paid_on']
            paid = parse_date(paid_str) if paid_str else None
            # compute reminder dates
            dates = []
            for n in (3, 7, 14):
                rd = add_business_days(due, n)
                if paid is None or rd < paid:
                    dates.append(rd.isoformat())
            # sort dates (they should be in order already)
            reminders[inv_id] = dates
    with open('reminders.json', 'w') as f:
        json.dump(reminders, f, indent=2)

if __name__ == '__main__':
    main()

